INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine IPv6-Adresse immer in 8 Blöcken dargestellt?', 2, '[{"text": "Nein", "correct": true, "because": "Kürzungsregeln erlauben weniger Blöcke"}, {"text": "Ja", "correct": false, "because": "Nullen können weggelassen werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits hat ein einzelner Block in der Hexadezimaldarstellung?', 3, '[{"text": "16", "correct": true, "because": "128 Bits durch 8 Blöcke"}, {"text": "32", "correct": false, "because": "Zu hoch für einen Block"}, {"text": "8", "correct": false, "because": "Zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeichen nutze ich für eine IPv6-Adresse?', 4, '[{"text": "0-9 und A-F", "correct": true, "because": "Hexadezimalformat"}, {"text": "0-9 und G-Z", "correct": false, "because": "Keine gültigen Hex-Zeichen"}, {"text": "Nur 0-9", "correct": false, "because": "Fehlen Buchstaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Jeder Block hat 4 Zeichen. b) Doppelpunkte trennen die Blöcke.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Standardformat"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Darstellung einer Adresse wie 2001:db8::1?', 5, '[{"text": "Führende Nullen", "correct": true, "because": "Werden gekürzt"}, {"text": "Doppelpunkte", "correct": false, "because": "Trennen Blöcke"}, {"text": "Hex-Zeichen", "correct": false, "because": "Kern der Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 128 Bits immer voll ausgeschrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kürzung ist erlaubt"}, {"text": "Ja", "correct": false, "because": "Nicht praktikabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für eine kompakte Adresse?', 3, '[{"text": ":: für mehrere Null-Blöcke", "correct": true, "because": "Kürzungsregel"}, {"text": ":0: für einzelne Nullen", "correct": false, "because": "Nicht maximal gekürzt"}, {"text": "0000 für alle Blöcke", "correct": false, "because": "Unnötig lang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln gelten für die Darstellung?', 5, '[{"text": "Führende Nullen weglassen", "correct": true, "because": "Vereinfacht Lesbarkeit"}, {"text": "Doppelte Nullen mit :: kürzen", "correct": true, "because": "Maximal einmal pro Adresse"}, {"text": "Leerzeichen einfügen", "correct": false, "because": "Ungültig"}, {"text": "Nur Zahlen nutzen", "correct": false, "because": "Hex benötigt A-F"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) :: darf nur einmal verwendet werden. b) Es ersetzt beliebig viele Blöcke. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Regeln für Kürzung"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Adresse zu lesen?', 4, '[{"text": "Doppelpunkte", "correct": false, "because": "Trennen Blöcke"}, {"text": "Hex-Werte", "correct": false, "because": "Kern der Adresse"}, {"text": "Binärcode", "correct": true, "because": "Hex ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind alle Blöcke gleich lang?', 2, '[{"text": "Ja", "correct": true, "because": "4 Zeichen pro Block"}, {"text": "Nein", "correct": false, "because": "Kürzung ändert nicht Länge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile einer Adresse sind essenziell?', 4, '[{"text": "Hex-Blöcke", "correct": true, "because": "Definieren Adresse"}, {"text": "Doppelpunkte", "correct": true, "because": "Strukturieren Darstellung"}, {"text": "Kommas", "correct": false, "because": "Ungültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2001:0db8::1 keine gültige Adresse ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Gültige gekürzte Form"}, {"text": "Ja", "correct": false, "because": "Erfüllt Hex-Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Adressdarstellung?', 3, '[{"text": "Lesbarkeit", "correct": true, "because": "Klarheit für Nutzer"}, {"text": "Maximale Länge", "correct": false, "because": "Kürzung bevorzugt"}, {"text": "Binärform", "correct": false, "because": "Nicht praktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 128 Bits sind Standard. b) IPv4 nutzt Hexadezimal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IPv4 ist dezimal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Hex-Darstellung?', 5, '[{"text": "Kompaktheit", "correct": true, "because": "Weniger Zeichen als Binär"}, {"text": "Lesbarkeit", "correct": true, "because": "Klar strukturiert"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Formatunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Darstellung unwichtig?', 3, '[{"text": "Blocktrennung", "correct": false, "because": "Struktur essenziell"}, {"text": "Hex-Zeichen", "correct": false, "because": "Kern der Adresse"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann :: beliebig oft vorkommen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur einmal erlaubt"}, {"text": "Ja", "correct": false, "because": "Regel verletzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jeder Block 16 Bits hat?', 3, '[{"text": "Ja", "correct": true, "because": "128 Bits auf 8 Blöcke"}, {"text": "Nein", "correct": false, "because": "Gleichmäßige Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kürzung wähle ich für 2001:0:0:0:0:0:0:1?', 4, '[{"text": "2001::1", "correct": true, "because": "Maximal gekürzt"}, {"text": "2001:0::1", "correct": false, "because": "Nicht vollständig gekürzt"}, {"text": "2001:0:0::1", "correct": false, "because": "Kann kürzer"}]');
